  "ok": false,
  "name": "draw_circle",
  "error": {
    "type": "invalid_params",
    "message": "'space' is a required property",
    "hint": "params must match the schema; a valid example is included",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "space": {
          "type": "string",
          "minLength": 1,
          "description": "'model' (design space, US survey feet) or a sheet id/name (paper space, inches), e.g. 'SH-004' or 'P-201'"
        },
        "layer": {
          "type": "string",
          "minLength": 1,
          "description": "layer name; defaults to the current layer"
        },
        "color": {
          "type": "string",
          "description": "override color; omit for ByLayer"
        },
        "linetype": {
          "type": "string",
          "enum": [
            "continuous",
            "dashed",
            "center",
            "hidden",
            "dot",
            "phantom"
          ],
          "description": "override linetype; omit for ByLayer"
        },
        "center": {
          "type": "array",
          "items": {
            "type": "number"
          },
          "minItems": 2,
          "maxItems": 2,
          "description": "[x, y]"
        },
        "radius": {
          "type": "number",
          "exclusiveMinimum": 0
        }
      },
      "required": [
        "space",
        "center",
        "radius"
      ],
      "additionalProperties": false
    },
    "example": {
      "space": "model",
      "center": [
        4350.0,
        7280.0
      ],
      "radius": 24.0
    }
  },
  "warnings": []
}

